3: class ThemeFonts extends ThemeExtension<ThemeFonts> {
4:   factory ThemeFonts({String? fontFamily = 'Inter', Color? color}) {
5:     late final TextStyle defaultStyle = TextStyle(fontFamily: fontFamily, color: color, fontWeight: FontWeight.normal);
6: 
7:     return ThemeFonts.raw(
8:       regular12: defaultStyle.copyWith(fontSize: 12),
9:       regular14: defaultStyle.copyWith(fontSize: 14),
10:       regular16: defaultStyle.copyWith(fontSize: 16),
11:       semiBold12: defaultStyle.copyWith(fontSize: 12, fontWeight: FontWeight.w700),
12:     );
13:   }
14: 
15:   const ThemeFonts.raw({
16:     required this.regular12,
17:     required this.regular14,
18:     required this.regular16,
19:     required this.semiBold12,
20:   });
21: 
22:   final TextStyle regular12;
23:   final TextStyle regular14;
24:   final TextStyle regular16;
25:   final TextStyle semiBold12;
26: 
27:   @override
28:   ThemeFonts copyWith({
29:     final TextStyle? regular12,
30:     final TextStyle? regular14,
31:     final TextStyle? regular16,
32:     final TextStyle? semiBold12,
33:   }) {
34:     return ThemeFonts.raw(
35:       regular12: regular12 ?? this.regular12,
36:       regular14: regular14 ?? this.regular14,
37:       regular16: regular16 ?? this.regular16,
38:       semiBold12: semiBold12 ?? this.semiBold12,
39:     );
40:   }
41: 
42:   @override
43:   ThemeFonts lerp(ThemeExtension<ThemeFonts>? other, double t) {
44:     if (other is! ThemeFonts) {
45:       return this;
46:     }
47: 
48:     return copyWith(
49:       regular12: TextStyle.lerp(regular12, other.regular12, t),
50:       regular14: TextStyle.lerp(regular14, other.regular14, t),
51:       regular16: TextStyle.lerp(regular16, other.regular16, t),
52:       semiBold12: TextStyle.lerp(semiBold12, other.semiBold12, t),
53:     );
54:   }
55: }

